CREATE TABLE t2(a,b); WITH RECURSIVE nums(value) AS (VALUES(1) UNION ALL SELECT value+1 FROM nums WHERE value<999) INSERT INTO t2(a,b) SELECT value, value FROM nums; UPDATE t2 SET a=NULL WHERE b%2==0; CREATE INDEX t2a1 ON t2(a) WHERE a IS NOT NULL; CREATE TABLE result AS SELECT count(*) AS n FROM t2 WHERE a IS NOT NULL;